//! Public library of rust-mcp-server.
//!
//! It is separated from `main.rs` to allow integration tests and so that
//! other Rust crates can consume the facade without going through the binary.

pub mod analysis;
pub mod model;
pub mod project_loader;
pub mod project_manager;
pub mod server;
pub mod tools;
pub mod transport;

// Crate version. Included from `OUT_DIR/version.rs` (generated by `build.rs`).
// `include!` puts the `VERSION` constant in the root module scope.
include!(concat!(env!("OUT_DIR"), "/version.rs"));

pub use project_manager::ProjectManager;
pub use server::RustMcpServer;
pub use transport::{ApiKeyStore, HttpTransportLauncher};
